/* Verilog code for error2 module */
module error2 (
    input  wire clk,        // 1 MHz clock input
    output reg [1:0] leds   // 2‑bit LED output
);

    // 500 ms @ 1 MHz = 500_000 clock cycles
    // 2^19 = 524_288 > 500_000, so 19‑bit counter is sufficient
    localparam integer COUNT_MAX = 500_000 - 1;
    reg [18:0] cnt;   // counter

    // Simple toggle: both LEDs on together, then both off
    always @(posedge clk) begin
        if (cnt == COUNT_MAX) begin
            cnt  <= 0;
            leds <= ~leds;          // toggle LEDs (00 <-> 11)
        end else begin
            cnt  <= cnt + 1'b1;
        end
    end

    // Power‑up default (all LEDs off)
    initial begin
        cnt  = 0;
        leds = 2'b00;
    end

endmodule

module binary_counter (
    input clk,
    input rst_n,
    output reg [3:0] Q
);

// Invert active‑low reset to obtain an active‑high async reset signal
wire rst = ~rst_n;

REG Q[4] @clk.pos rst.pos->4'b0000 PORT
  * -> Q + 1

// Verilog implementation of a 4‑to‑1 multiplexer (MUX4)
// The module selects one of the four 1‑bit inputs based on a 2‑bit select signal.
// If sel = 00 → out = in[0]
//    sel = 01 → out = in[1]
//    sel = 10 → out = in[2]
//    sel = 11 → out = in[3]

`timescale 1ns/1ps

module MUX4 (
    input  wire [3:0] in,   // four 1‑bit data inputs
    input  wire [1:0] sel,  // 2‑bit select signal
    output wire       out   // selected output (1‑bit)
);

    // Combinational logic using a ternary operator (cond ? t : f)
    assign out = (sel == 2'b00) ? in[0] :
                 (sel == 2'b01) ? in[1] :
                 (sel == 2'b10) ? in[2] :
                                   in[3];

    // Alternative implementation (case statement) – uncomment if preferred
    // always @* begin
    //     case (sel)
    //         2'b00: out = in[0];
    //         2'b01: out = in[1];
    //         2'b10: out = in[2];
    //         2'b11: out = in[3];
    //         default: out = 1'bx; // should never happen
    //     endcase
    // end

endmodule

// four_bit_adder – 4‑bit combinational adder
// Ports (fixed module header):
//   input  [3:0] A, B
//   input        Cin
//   output [3:0] Sum
//   output       Cout

// Sum and carry‑out are pure combinational logic.
// The full 5‑bit result of A+B+Cin is used to extract the lower 4 bits
// (the Sum) and the most‑significant bit (the carry‑out).

Sum = (A + B + Cin)[3:0]
Cout = (A + B + Cin)[4]

