module clock_gate(
  input CLK, // clock signal
  input EN,  // enable signal
  input TE,  // test enable signal
  output ENCLK // gated clock signal
);

  // The gating logic follows the specification:
  //   TE = 1 -> ENCLK forced high (override)
  //   otherwise, EN = 1 -> pass CLK through
  //   otherwise (EN = 0) -> drive low
  // This can be described with a simple combinational assignment.
  assign ENCLK = TE ? 1'b1 : (EN ? CLK : 1'b0);

endmodule

