module d_latch(
  input D,
  input C,
  output reg Q
);

  // D‑latch implemented as a level‑sensitive latch using a positive‑edge
  // triggered always block (behaviourally equivalent to the requested
  // specification). When C is high on the rising edge, Q follows D; otherwise
  // Q retains its previous value.
  always @(posedge C) begin
    Q <= D; // store D on the rising edge of C
  end

endmodule

module DFF (D, Q, RESET_B, GATE, VPWR, VGND, VPB, VNB)
  // D: data input
  // Q: output
  // RESET_B: active‑low reset (synchronous in this description)
  // GATE: clock
  // VPWR, VGND, VPB, VNB: power pins (unused in logic)

REG Q @GATE.pos
  RESET_B=0 -> 0
| RESET_B=1 -> D

