module sky130_fd_sc_ms__dlrtp (
    output Q,
    input  D,
    input  GATE,
    input  RESET_B,
    // Power pins
    input  VPWR,
    input  VGND,
    input  VPB,
    input  VNB
);

    // Internal latch storage
    reg Q_int;
    assign Q = Q_int;

    // Level‑sensitive latch with an *active‑high* asynchronous reset.
    //  * When RESET_B = 1 → Q is forced to 0.
    //  * When RESET_B = 0 and GATE = 1 → Q follows D.
    //  * When RESET_B = 0 and GATE = 0 → Q holds its previous value.
    always @(*) begin
        if (RESET_B) begin
            Q_int = 1'b0;            // reset overrides everything
        end else if (GATE) begin
            Q_int = D;               // transparent (gate high)
        end                               // otherwise Q_int retains its value (latch hold)
    end

endmodule

