// 4‑bit binary to Gray code converter (VSL)
// Ports (fixed by surrounding Verilog wrapper):
//   in  [3:0]  – binary input
//   out [3:0]  – Gray‑code output

out[3] = in[3]
out[2] = in[3] ^ in[2]
out[1] = in[2] ^ in[1]
out[0] = in[1] ^ in[0]

// ------------------------------------------------------------------
// Simple test sequence (illustrative – not a full Verilog testbench)
// Apply every 4‑bit value and check the expected Gray code.
// Expected mapping (binary -> Gray):
//   0000 -> 0000
//   0001 -> 0001
//   0010 -> 0011
//   0011 -> 0010
//   0100 -> 0110
//   0101 -> 0111
//   0110 -> 0101
//   0111 -> 0100
//   1000 -> 1100
//   1001 -> 1101
//   1010 -> 1111
//   1011 -> 1110
//   1100 -> 1010
//   1101 -> 1011
//   1110 -> 1001
//   1111 -> 1000
// A Verilog testbench can iterate over the 16 values, drive 'in',
// wait a delta‑cycle and compare 'out' with the table above.

// Watchdog Timer (WDT)
// Parameters: timeout - number of clock cycles before watchdog expires
// Adjust the literal value in the guard cnt=TIMEOUT as needed.

REG cnt[31] @clk.pos reset.sync->0
  rst=1 -> 0
| rst=0 -> cnt + 1
| *     -> cnt

COMB wdt
  cnt=TIMEOUT -> 1
| *            -> 0

module four_to_one(
    input  wire in1,
    input  wire in2,
    input  wire in3,
    input  wire in4,
    output wire out
);
    // Priority logic: out = 1 if the highest‑priority input that is 1 is present.
    // The description only mentions in1‑in3, so in4 is not used in the priority chain.
    assign out = in1 | (~in1 & in2) | (~in1 & ~in2 & in3);
endmodule

