module add_sub_4bit (
    input  wire [3:0] A,
    input  wire [3:0] B,
    input  wire       C,   // C=0 → add, C=1 → subtract
    output wire [3:0] S,   // valid when C=0
    output wire [3:0] D,   // valid when C=1
    output wire       Cout // carry‑out (or borrow‑out)
);

    // Two's‑complement subtraction can be expressed as
    //   A – B  =  A + (~B + 1)
    // The term (~B + 1) is obtained by inverting B when C=1 and adding the
    // control bit as the carry‑in.
    wire [3:0] B_xor = B ^ {4{C}};   // B when C=0,  ~B when C=1
    wire [4:0] result = A + B_xor + C; // extra bit holds carry/borrow

    assign S    = result[3:0];   // sum (valid for C=0)
    assign D    = result[3:0];   // difference (valid for C=1)
    assign Cout = result[4];    // carry‑out for add, borrow‑out for sub

endmodule

