//------------------------------------------------------------------------------
//  Clock‑gating block
//  --------------------------------------------------------------
//  Inputs : CLK  – system clock
//           EN   – enable (active high)
//           TE   – transparent enable (active high)
//  Output : ENCLK – gated clock
//
//  Behaviour:
//      EN = 1 && TE = 0  => ENCLK follows CLK
//      otherwise         => ENCLK = 0
//------------------------------------------------------------------------------
module clk_gate (
    input  wire CLK,   // main clock
    input  wire EN,    // enable (high = allow clock)
    input  wire TE,    // transparent enable (high = force clock low)
    output wire ENCLK  // gated clock output
);

    // Simple combinational gating.  The expression is evaluated on every edge of
    // CLK, but because the output is a clock it should be synthesized into a
    // proper clock‑gating cell by the tool‑chain (or you can replace it with a
    // vendor‑specific cell such as `CLKGATE`.
    assign ENCLK = (EN && !TE) ? CLK : 1'b0;

endmodule
//------------------------------------------------------------------------------
```
**Explanation of the code**
1. **Port list** – matches exactly the specification (CLK, EN, TE, ENCLK).  No extra ports are introduced.
2. **Logic** – the conditional operator implements the required truth‑table:
   * `EN && !TE` is true only when EN is high **and** TE is low → forward the clock.
   * In all other cases the expression evaluates to `0`, forcing ENCLK low.
3. **Synthesis‑friendly** – the single `assign` statement is the canonical way to describe a clock‑gate in RTL.  Most FPGA/ASIC synthesis tools recognize this pattern and replace it with a low‑power gated‑clock cell, avoiding glitches that could otherwise appear with a naïve gates‑level implementation.

You can instantiate this module anywhere you need a gated clock, for example:
```verilog
// Example usage inside a larger design
wire gated_clk;
clk_gate u_gate (
    .CLK   (sys_clk),
    .EN    (run),
    .TE    (test_mode),
    .ENCLK (gated_clk)
);
```
