module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    input Clock,
    output [3:0] Sum,
    output Cout
);

    // Internal registers to hold the registered sum and carry‑out
    reg [3:0] sum_reg;
    reg       cout_reg;

    // Drive the module outputs
    assign Sum  = sum_reg;
    assign Cout = cout_reg;

    // Sequential implementation – all calculations are performed on the
    // rising edge of Clock.  No built‑in arithmetic operators (+, -) are used;
    // the adder is built from bitwise XOR, AND and OR primitives, i.e. a
    // cascade of full‑adder cells.
    always @(posedge Clock) begin
        // ----- Bit 0 -----
        // Sum0 = A0 ⊕ B0 ⊕ Cin
        sum_reg[0] = A[0] ^ B[0] ^ Cin;
        // Carry out of bit 0
        // C1 = (A0 & B0) | (A0 & Cin) | (B0 & Cin)
        reg c1;
        c1 = (A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin);

        // ----- Bit 1 -----
        sum_reg[1] = A[1] ^ B[1] ^ c1;
        reg c2;
        c2 = (A[1] & B[1]) | (A[1] & c1) | (B[1] & c1);

        // ----- Bit 2 -----
        sum_reg[2] = A[2] ^ B[2] ^ c2;
        reg c3;
        c3 = (A[2] & B[2]) | (A[2] & c2) | (B[2] & c2);

        // ----- Bit 3 -----
        sum_reg[3] = A[3] ^ B[3] ^ c3;
        // Final carry‑out
        cout_reg = (A[3] & B[3]) | (A[3] & c3) | (B[3] & c3);
    end

endmodule

