module clock_divider #(
    parameter integer DIV_FACTOR = 8 // Must be >= 2
) (
    input  wire clk_in,
    input  wire rst,        // active‑high synchronous reset
    output reg  clk_out
);
    // Calculate the minimum width required to hold DIV_FACTOR‑1
    localparam WIDTH = $clog2(DIV_FACTOR);
    localparam [WIDTH-1:0] MAX_COUNT = DIV_FACTOR - 1;

    reg [WIDTH-1:0] cnt;

    // Counter and output toggle logic
    always @(posedge clk_in) begin
        if (rst) begin
            cnt     <= {WIDTH{1'b0}};
            clk_out <= 1'b0;
        end else begin
            if (cnt == MAX_COUNT) begin
                cnt     <= {WIDTH{1'b0}}; // wrap‑around
                clk_out <= ~clk_out;      // toggle output
            end else begin
                cnt <= cnt + 1'b1;
            end
        end
    end
