  state=IDLE & divisor_reg=0 -> DONE            // divide‑by‑zero → finish with zero remainder
| state=IDLE                     -> LOAD
| state=LOAD                     -> CALC
| state=CALC & cnt=16            -> DONE
| *                              -> state

