// sirv_aon_porrst.v
// Power‑On Reset generator for ASIC, tied‑high for FPGA
// ----------------------------------------------------
//   - Output: porrst_n (active‑low reset)
//   - In FPGA builds the output is permanently 1'b1 (no reset circuit).
//   - In ASIC builds a simple counter creates a delayed de‑assertion.
//   - The choice is made with the synthesis macro `FPGA` (define it for FPGA).
//   - No external libraries, self‑contained, <200 lines.

`timescale 1ns/1ps

module sirv_aon_porrst (
    output wire porrst_n
);

    // ---------------------------------------------------------------------
    // Platform selection: define FPGA (e.g., -DFPGA) for FPGA builds.
    // ---------------------------------------------------------------------
`ifdef FPGA
    // -----------------------------------------------------------------
    // FPGA: there is no POR circuit – tie the reset output high.
    // -----------------------------------------------------------------
    assign porrst_n = 1'b1; // active‑low reset released
`else
    // -----------------------------------------------------------------
    // ASIC implementation – generate a power‑on reset using a counter.
    // -----------------------------------------------------------------
    // Parameters – adjust for required reset width and duration.
    //   CNT_WIDTH: number of bits for the counter (minimum to hold MAX_COUNT).
    //   MAX_COUNT: number of clock cycles the reset stays asserted.
    //   CLK:     use the default system clock (assumed already available).
    //   RST_N:   asynchronous reset (active‑low). Here we assume a power‑
    //            on condition, so we treat it as always asserted.
    // -----------------------------------------------------------------
    parameter CNT_WIDTH = 16;                // enough for typical POR
    parameter MAX_COUNT = 16'hFFFF;          // hold reset for 65535 cycles

    // -----------------------------------------------------------------
    // Clock source – for ASIC we expect a dedicated POR clock. Here we use
    // the generic system clock `clk`. In the real design this should be
    // replaced by a low‑frequency, always‑running clock.
    // -----------------------------------------------------------------
    wire clk;
    // The `clk` net should be bound by the top‑level design. For illustration
    // we create an implicit wire that must be driven from outside.

    // -----------------------------------------------------------------
    // Counter that increments on every clock edge until it reaches MAX_COUNT.
    // While the counter is less than MAX_COUNT the reset stays asserted
    // (porrst_n = 0). After reaching MAX_COUNT the counter stops and the reset
    // is released (porrst_n = 1).
    // -----------------------------------------------------------------
    reg [CNT_WIDTH-1:0] cnt;
    wire cnt_done = (cnt == MAX_COUNT);

    // Simple synchronous counter with enable until done.
    always @(posedge clk) begin
        if (!cnt_done)
            cnt <= cnt + 1'b1;
        else
            cnt <= cnt; // hold value
    end

    // Active‑low reset is asserted while counter not done.
    assign porrst_n = cnt_done ? 1'b1 : 1'b0;
`endif

endmodule
