// Verilog implementation of an asynchronous reset release circuit
// When reset (active‑low) is asserted, the released reset output (rst) is de‑asserted (high).
// When reset is released (goes high), rst goes low for 10 clock cycles and then returns high.

module async_reset_release (
    input  wire reset,   // async active‑low reset input
    input  wire clk,     // system clock
    output reg  rst      // released reset, active‑low pulse
    );

    // Counter width: enough to count 0‑10 (4 bits)
    localparam CNT_WIDTH = 4;
    localparam PULSE_LEN  = 10; // number of clock cycles the reset stays active (low)

    reg [CNT_WIDTH-1:0] cnt;

    // Asynchronous reset handling
    always @(posedge clk or negedge reset) begin
        if (!reset) begin
            // Reset asserted: output inactive (high) and clear counter
            rst  <= 1'b1;   // inactive state
            cnt  <= {CNT_WIDTH{1'b0}};
        end else begin
            // Normal operation after reset is released
            if (cnt < PULSE_LEN) begin
                rst <= 1'b0;          // active (low) during pulse
                cnt <= cnt + 1'b1;
            end else begin
                rst <= 1'b1;          // return to inactive after pulse
                cnt <= cnt;           // hold counter (no further counting)
            end
        end
    end

endmodule

