    // asynchronous preset, synchronous D capture
    always @ (posedge C or posedge PRE) begin
        if (PRE) begin
            Q <= #FLOP_DELAY 1'b1;   // async preset forces Q high
        end else begin
            Q <= #FLOP_DELAY D;      // normal D‑capture on clock edge
        end
    end
endmodule
